diff --git a/src/ui/lib/reading-progress.ts b/src/ui/lib/reading-progress.ts
index 91d5404..a79b5a8 100644
--- a/src/ui/lib/reading-progress.ts
+++ b/src/ui/lib/reading-progress.ts
@@ -63,3 +63,12 @@ export function reviewReadingPaths(review: {
   }
   return paths;
 }
+
+/** Binary paths git skipped. They stay out of the file total and are named beside it. */
+export function skippedBinaryNote(skipped: readonly { path: string; reason: string }[]): string | null {
+  const paths = skipped.flatMap((file) => (file.reason === "binary" ? [file.path] : []));
+  if (paths.length === 0) {
+    return null;
+  }
+  return `${paths.join(", ")} skipped`;
+}

